  "interactiveHelp.started": "インタラクティブヘルプがオンです。ボタン、入力欄、ウィンドウをクリックすると説明が読めます。Escで終わります。",
  "interactiveHelp.ended": "インタラクティブヘルプがオフになりました",
  "shortcuts.interactiveHelp": "インタラクティブヘルプのオンとオフ",
  "installHint.chromium": "アドレスバー右側のアイコン、またはブラウザーメニューの「アプリとしてインストール」からインストールします。",
  "installHint.safariMac": "Safariの場合: ファイルメニュー → 「Dockに追加」。",
  "installHint.ios": "Safariの場合: 共有アイコン → 「ホーム画面に追加」。",
  "installHint.firefox": "Firefoxではアプリをインストールできません。それでもlayerlingはこのタブでオフラインでも起動します。",
  "welcome.moreLanguagesTitle": "あなたの言葉で",
  "welcome.moreLanguagesBody": "このプログラムとガイドは、英語、ドイツ語、ほか17の言葉で使えます。言葉の一覧は、画面のいちばん右上と、スタートページの設定にあります。",
  "welcome.moreOfflineTitle": "オフラインで動作",
  "welcome.moreOfflineBody": "最初の訪問の後は、インターネットがなくてもlayerlingは起動します。通常のプログラムのようにインストールでき、デザインはあなたのコンピューターに残ります。",
  "welcome.moreAiTitle": "AIと一緒に作る",
  "welcome.moreAiBody": "MCPインターフェースを通じて、AIアシスタントが自分で開いたエディターでシェイプを作成・編集できます。自分で動かすコピー（npm run dev、またはDockerイメージ）が必要です。layerling.comではAI接続はオフになっています。",
  "welcome.morePointsTitle": "基準点",
  "welcome.moreSearchTitle": "コマンド検索",
  "welcome.moreSimplifyTitle": "メッシュの簡略化",
  "welcome.moreSimplifyBody": "三角形が非常に多い読み込みメッシュを、前後の比較表示とスライダーで数分の一に減らします。切り抜き、グループ化、ドラッグが軽快なままになります。",
  "welcome.moreHistoryTitle": "履歴",
  "welcome.moreLookTitle": "好みの見た目に",
  "welcome.moreLookBody": "背景と作業平面、X・Y・Zの軸矢印、各ボディのエッジ線、スケッチの色、コントラスト、影、光の向きを設定で変えられます。たとえば暗いボディ同士が溶け合って見えないように。遅いコンピューターでは、高速モードで負荷の高いものを一度にすべてオフにできます。",
  "welcome.moreTabletTitle": "タブレットで",
  "welcome.moreTabletBody": "1 本指はマウスの左ボタンのようにデザインを操作し、2 本指でビューを拡大・移動します。Bluetooth キーボードでショートカットも使えます。",
  "welcome.moreHistoryBody": "スライダーでプロジェクトの以前の状態を何も変えずに振り返れます。その状態をエクスポートしたり、そこから新しいプロジェクトを始めたり、その状態から個々のオブジェクトを戻したりできます。",
  "welcome.moreDrawingTitle": "工作用の図面",
  "welcome.moreDrawingBody": "エクスポート → 図面: 正面、上面、側面を、ISOの用紙に1:1で、全体の寸法、かくれた線、丸い穴の表つきで出力します。PDFまたはSVGで、印刷したり、旋盤やフライス盤に持っていったりできます。",
  "welcome.moreSearchBody": "Ctrl+Kを押してツール、シェイプ、コマンドの名前を入力すると、すぐにそこへ移動できます。英語でもドイツ語でも使え、各項目の横にキーボードショートカットが表示されます。デザイン内のボディも名前で見つかります。",
  "welcome.moreHelpTitle": "インタラクティブヘルプ",
  "welcome.moreHelpBody": "Shift+F1 か疑問符を押してから、ボタンや欄、ウィンドウをクリック。小さなウィンドウにガイドの該当箇所が表示されます。",
  "welcome.morePointsBody": "ボディを右クリックすると、その中心、角、エッジの中点に、プリントされずシェイプがスナップする点を付けられます。これで穴を別のパーツの中心にぴったり置けます。",
  "welcome.videosTitle": "layerlingについての動画",
  "welcome.videosHint": "このプロジェクトではなく、他の方が作ったものです。リンクは新しいタブでYouTubeを開きます。クリックするまで何も読み込まれません。",
  "welcome.help": "エディターの「ヘルプ」グループには短いガイドと、すべてのキーボードショートカットの一覧があります。フッターの「バグ報告」は、ディスカッションやGitHubでの報告に必要なものをすべて含めてデザインを保存します。",
  "welcome.guideLink": "図入りの完全なユーザーガイドを読む",
