  "welcome.moreHolePatternTitle": "穴パターン",
  "welcome.moreHolePatternBody": "ボディの平らな面をクリックして、穴を面全体に広げます。丸、正方形、長方形、六角形、長穴を格子状または千鳥状に並べ、間隔、エッジまでの余白、深さ（ボディ全体を貫通、または決めた深さ）を設定できます。作成前にプレビューで穴を確認できます。作成した穴は通常の穴のままで、ボディとグループ化されます。通気口、スピーカーグリル、かご、ケースなどに便利です。",
  "welcome.moreFaceTitle": "面を押し出す",
  "welcome.moreFaceBody": "ボディの平らな面を押し出したりポケットを彫り込んだりできます。縁からのオフセット、角の丸め、深さを指定し、プレビューで確認。読み込んだ STL にも使えます。",
  "guide.select.holePattern": "穴パターン（ツールバーのパターンの隣のボタン、ボディの右クリック、または Ctrl+K）: 平らな面をクリックし、穴のシェイプ、サイズ、間隔、配置、余白、深さを設定します。穴はプレビューとして表示され、「作成」でボディとグループ化された穴として追加されます。グループ解除で再び自由になります。",
  "guide.select.faceTool": "面（ツールバーの穴パターンの隣のボタン、ボディの右クリック、または Ctrl+K）: 平らな面をクリックし、「外」か「内」を選んで、エッジからの余白、角の半径、深さを決めます。足されるものは、ボディとグループ化されたスケッチボディです。",
