  "thread.axialClearanceHint": "クリアランスに加えて、ねじの軸方向に与える余分な遊び（mm）です。直径はそのままで、ナットの各歯がこの分だけ薄くなります。横にがたつかずに軽く回るねじにするには、クリアランスを0.2〜0.3程度にして、ここに0.2を決めます。0ではクリアランスだけで遊びが決まり、フランクの開きはその半分程度にしかなりません。",
  "thread.clearanceHint": "直径全体に加える余分な空間です。プリントしたねじには思ったより多く必要です。フランク間のすき間はこの約半分にしかなりません。0.3程度できつめ、0.4が標準、0.5でゆるめです。まずテスト用の組を印刷してください。",
