  "prop.gridfinityOpeningDistanceRight": "右の距離",
  "gridfinity.openingHint": "深さはふちの上（ふちがないときはビンの上）から、距離は開口部をそろえる端からはかります。幅いっぱいに底まで開けると、その側はすべて開きます。それより小さい開口部では、その側の角と横のふちが残ります。",
  "prop.gridfinityOpeningCorner": "開口部の角",
  "prop.gridfinityOpeningCornerSize": "開口部の角の大きさ",
  "gridfinity.openingCornerHint": "壁の外から見た、開口部の上と下の角です。0.5 mmより小さいと四角いままです。側面全体に開けた開口部には、上の角はありません。",
  "prop.gridfinityPaddingBack": "奥の余白",
