  "prop.gridfinityPaddingRight": "右の余白",
  "gridfinity.paddingHint": "グリッドの外側にある、中までつまったふちです。マスの数でちょうど割り切れない引き出しも、ベースプレートでうめられます。余白を変えると、マスの数はそのままで、プレートの大きさが変わります。",
  "prop.gridfinityCornerRadius": "角の半径",
  "gridfinity.cornerRadiusHint": "プレートの外側の4つの角の半径です。Gridfinityの仕様の図では4 mmで、0にすると引き出しの角にぴったり入る四角い角になります。くぼみの丸みは変わらないので、ビンはこれまでどおり入ります。",
